metrics.workdir_dsl:
workspace "Bookshop" "A simple online bookshop" {

    !identifiers hierarchical

    model {
        customer = person "Customer" "A customer who browses and buys books online"

        bookshop = softwareSystem "Bookshop" "An online bookshop where customers browse the catalogue and order books" {
            webStore = container "Web Store" "The web application that lets customers browse the catalogue and place orders" "Java/Spring Boot"
            orderProcessor = container "Order Processor" "Processes and fulfils customer orders" "Java/Spring Boot"
        }

        customer -> bookshop.webStore "browses the catalogue and places orders via" "HTTPS"
        bookshop.webStore -> bookshop.orderProcessor "sends new orders to" "JSON/HTTP"
    }

    views {
        systemContext bookshop "SystemContext" {
            include *
            autoLayout
            title "System Context for Bookshop"
        }
    }
}
